const dishes = [
  { name: "Neer Dosa", cuisine: "Mangalorean", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Paper-thin silky rice crepes from a watery batter.", ingredients: ["rice flour", "water", "salt", "coconut oil"], extraNeeded: ["coconut oil"], instructions: ["Soak raw rice for 4-6 hours, then grind with water to a very thin watery batter.", "Add salt to taste. The batter should be thinner than regular dosa batter.", "Heat a non-stick pan on medium heat and grease lightly with coconut oil.", "Pour a ladleful of batter and swirl quickly to spread thin — do not spread with a spoon.", "Cover and cook for 1-2 minutes until edges lift and top looks set.", "Fold and serve immediately with coconut chutney or chicken curry."] },
  { name: "Golibaje", cuisine: "Mangalorean", time: "25 min", difficulty: "Easy", diet: ["vegetarian"], description: "Crispy golden fritters of maida and coconut — a beloved tea-time snack.", ingredients: ["maida", "flour", "coconut", "curd", "yogurt", "green chilli", "ginger", "baking soda"], extraNeeded: ["oil"], instructions: ["Mix maida, grated coconut, chopped green chilli, grated ginger, and salt in a bowl.", "Add curd and mix to form a thick batter. Rest for 15 minutes.", "Add a pinch of baking soda and mix well just before frying.", "Heat oil in a deep pan to medium-high heat.", "Drop small spoonfuls of batter into the oil and fry until golden brown.", "Drain on paper towel and serve hot with coconut chutney."] },
  { name: "Kori Rotti", cuisine: "Tulu Nadu", time: "50 min", difficulty: "Medium", diet: ["non-veg"], description: "Crispy rice crackers drenched in fiery chicken curry.", ingredients: ["chicken", "coconut", "onion", "tomato", "red chilli", "coriander", "turmeric", "garlic"], extraNeeded: ["kori rotti crackers"], instructions: ["Dry roast coconut, red chillies, coriander seeds and grind to a smooth paste.", "Fry onions in oil until golden, add garlic, ginger and cook 2 minutes.", "Add tomatoes and cook until soft. Add the ground masala and turmeric.", "Add chicken pieces, mix well and cook on high heat for 5 minutes.", "Add water and simmer 20-25 minutes until chicken is tender and oil separates.", "Just before serving, break kori rotti crackers into a bowl and pour hot curry on top."] },
  { name: "Mangalore Buns", cuisine: "Mangalorean", time: "30 min", difficulty: "Easy", diet: ["vegetarian"], description: "Fluffy deep-fried banana bread rolls.", ingredients: ["banana", "maida", "flour", "sugar", "curd", "yogurt", "cumin", "baking soda"], extraNeeded: ["oil"], instructions: ["Mash ripe bananas thoroughly in a bowl until smooth.", "Add sugar, curd, cumin seeds, baking soda and salt. Mix well.", "Add maida gradually and knead into a soft, slightly sticky dough. Rest 15 minutes.", "Divide dough into balls and roll into thick circles (slightly thicker than puri).", "Heat oil in a kadai. Fry the buns on medium heat until puffed and golden on both sides.", "Serve hot with coconut chutney or sambar."] },
  { name: "Fish Curry", cuisine: "Coastal Karnataka", time: "35 min", difficulty: "Medium", diet: ["non-veg", "gluten-free"], description: "Bold tangy coconut curry with kokum and roasted spices.", ingredients: ["fish", "coconut", "onion", "tomato", "red chilli", "turmeric", "kokum", "tamarind", "ginger", "garlic"], extraNeeded: ["curry leaves"], instructions: ["Dry roast red chillies, coriander seeds and grind with coconut and tamarind to a smooth paste.", "Fry onions in oil until golden, add garlic and ginger, cook 2 minutes.", "Add the ground masala paste and turmeric. Cook on medium heat for 5 minutes.", "Add kokum pieces and enough water to make a thick gravy.", "Bring to a boil, add fish pieces and cook gently for 8-10 minutes.", "Finish with curry leaves and serve with rice or neer dosa."] },
  { name: "Chicken Ghee Roast", cuisine: "Mangalorean", time: "50 min", difficulty: "Medium", diet: ["non-veg", "gluten-free"], description: "Intensely spiced dry chicken slow-roasted in clarified butter.", ingredients: ["chicken", "ghee", "butter", "red chilli", "garlic", "tamarind", "pepper", "cumin", "coriander"], extraNeeded: ["curry leaves", "jaggery"], instructions: ["Dry roast red chillies, pepper, cumin and coriander seeds. Grind with tamarind to a paste.", "Marinate chicken in half the masala paste and turmeric for 30 minutes.", "Heat ghee in a heavy pan, add remaining masala and cook until oil separates.", "Add marinated chicken and cook on high heat for 5 minutes.", "Reduce heat, add jaggery and cook uncovered until dry and chicken is coated.", "Finish with curry leaves. Serve with neer dosa or appam."] },
  { name: "Prawn Sukka", cuisine: "Coastal Karnataka", time: "30 min", difficulty: "Easy", diet: ["non-veg", "gluten-free"], description: "Dry-spiced prawns tossed with fresh grated coconut and curry leaves.", ingredients: ["prawns", "shrimp", "coconut", "onion", "red chilli", "turmeric", "curry leaves", "garlic"], extraNeeded: ["coriander seeds"], instructions: ["Clean and devein prawns. Marinate with turmeric and salt for 10 minutes.", "Dry roast red chillies and coriander seeds. Grind coarsely with coconut.", "Fry onions and garlic in oil until golden brown.", "Add the ground masala and cook for 3 minutes.", "Add prawns and toss on high heat for 5-6 minutes until cooked.", "Add curry leaves, toss and serve dry with rice."] },
  { name: "Kane Fry", cuisine: "Mangalorean", time: "20 min", difficulty: "Easy", diet: ["non-veg", "gluten-free"], description: "Lady fish in a fiery red chilli-turmeric marinade, coated in semolina and shallow-fried.", ingredients: ["fish", "red chilli", "turmeric", "garlic", "semolina", "rava", "lemon", "ginger"], extraNeeded: ["oil"], instructions: ["Clean lady fish and make diagonal cuts on both sides.", "Grind red chillies, garlic, ginger with lemon juice to a thick paste.", "Apply the paste all over the fish and marinate for 20 minutes.", "Coat each fish in fine semolina, pressing gently so it sticks.", "Heat oil in a flat pan. Shallow fry fish 3-4 minutes per side until crispy.", "Serve immediately with sliced onions and lemon wedges."] },
  { name: "Bangude Pulimunchi", cuisine: "Tulu Nadu", time: "40 min", difficulty: "Medium", diet: ["non-veg", "gluten-free"], description: "Mackerel in a sour-spicy tamarind-chilli gravy.", ingredients: ["mackerel", "fish", "tamarind", "red chilli", "onion", "garlic", "turmeric", "pepper"], extraNeeded: ["kokum"], instructions: ["Clean mackerel and make cuts. Marinate with turmeric and salt.", "Grind red chillies, pepper and garlic to a coarse paste.", "Fry onions in oil until golden. Add the ground masala and cook 3 minutes.", "Add tamarind extract and kokum, bring to a boil.", "Add mackerel pieces gently and simmer 10-12 minutes.", "Serve hot with rice — the gravy should be thick, sour and spicy."] },
  { name: "Pathrade", cuisine: "Coastal Karnataka", time: "60 min", difficulty: "Hard", diet: ["vegetarian", "vegan", "gluten-free"], description: "Taro leaves spread with spiced rice-coconut paste, rolled and steamed.", ingredients: ["colocasia", "taro", "rice flour", "coconut", "red chilli", "tamarind", "jaggery"], extraNeeded: ["turmeric leaf"], instructions: ["Soak rice and grind with coconut, red chillies, tamarind and jaggery to a thick paste.", "Wash taro leaves and dry completely. Remove thick stems.", "Spread a layer of the rice-coconut paste evenly on each leaf.", "Stack leaves on top of each other with paste between each layer.", "Roll tightly, tie with string and steam for 30-35 minutes.", "Cool, slice into rounds and shallow fry in coconut oil until crispy on both sides."] },
  { name: "Coconut Chutney", cuisine: "South Indian", time: "10 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Fresh coconut blended with green chilli and ginger, tempered with mustard seeds.", ingredients: ["coconut", "green chilli", "ginger", "mustard seeds", "curry leaves", "coriander"], extraNeeded: ["chana dal"], instructions: ["Blend fresh coconut, green chilli, ginger and salt with a little water to a smooth paste.", "Transfer to a bowl and adjust salt.", "Heat oil in a small pan. Add mustard seeds and let them splutter.", "Add chana dal and fry until golden. Add curry leaves.", "Pour the tempering over the chutney and mix.", "Serve with idli, dosa or vada."] },
  { name: "Bangda Fry", cuisine: "Mangalorean", time: "25 min", difficulty: "Easy", diet: ["non-veg", "gluten-free"], description: "Whole mackerel in Mangalorean masala pan-fried till crisp.", ingredients: ["mackerel", "fish", "red chilli", "turmeric", "garlic", "semolina", "rava", "lemon"], extraNeeded: ["oil"], instructions: ["Clean mackerel and make 3-4 diagonal cuts on each side.", "Grind red chillies, garlic, turmeric with lemon juice to a paste.", "Rub the paste into the fish and inside the cuts. Marinate 20 minutes.", "Coat fish in semolina on all sides.", "Heat oil in a flat pan and fry fish on medium heat 4 minutes per side.", "Serve hot with onion rings and kokum-based sol kadhi."] },
  { name: "Idli Sambar", cuisine: "South Indian", time: "40 min", difficulty: "Medium", diet: ["vegetarian", "vegan", "gluten-free"], description: "Pillowy steamed rice cakes with a lentil-vegetable stew.", ingredients: ["rice", "urad dal", "toor dal", "lentil", "onion", "tomato", "mustard seeds"], extraNeeded: ["curry leaves", "tamarind"], instructions: ["Soak rice and urad dal separately for 6 hours. Grind to smooth batter. Ferment overnight.", "Add salt to batter, pour into greased moulds and steam 10-12 minutes.", "For sambar: cook toor dal with turmeric until soft. Mash well.", "Fry onions, tomatoes with sambar powder. Add cooked dal and tamarind extract.", "Add vegetables of choice and simmer 10 minutes. Temper with mustard seeds and curry leaves.", "Serve hot idlis with sambar and coconut chutney."] },
  { name: "Egg Fried Rice", cuisine: "Indo-Chinese", time: "20 min", difficulty: "Easy", diet: ["vegetarian"], description: "Wok-tossed rice with scrambled eggs, soy sauce and spring onions.", ingredients: ["egg", "rice", "onion", "soy sauce", "garlic", "ginger", "spring onion", "carrot"], extraNeeded: ["pepper"], instructions: ["Cook rice al dente, spread on a tray and cool completely (day-old rice works best).", "Heat oil in a wok on high heat. Add garlic and ginger, stir-fry 30 seconds.", "Add chopped onion and carrot. Stir-fry on high heat for 2 minutes.", "Push vegetables to the side, scramble eggs in the empty space.", "Add rice, soy sauce, pepper and toss everything together on high heat.", "Garnish with spring onions and serve hot."] },
  { name: "Dal Tadka", cuisine: "North Indian", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Yellow lentils simmered until creamy, finished with a sizzling tempering.", ingredients: ["toor dal", "moong dal", "lentil", "dal", "onion", "tomato", "garlic", "cumin", "turmeric", "red chilli"], extraNeeded: ["ghee"], instructions: ["Wash and pressure cook toor dal with turmeric until very soft (3-4 whistles).", "Mash the dal and add water to get a pourable consistency.", "Fry onions in oil until golden. Add garlic, cook 1 minute.", "Add tomatoes and cook until mushy. Add red chilli powder.", "Add this masala to the dal and simmer 10 minutes. Adjust salt.", "For tadka: heat ghee, add cumin, dry red chilli and pour sizzling over the dal."] },
  { name: "Paneer Butter Masala", cuisine: "North Indian", time: "35 min", difficulty: "Medium", diet: ["vegetarian", "gluten-free"], description: "Soft cottage cheese in a velvety tomato-cashew gravy.", ingredients: ["paneer", "cottage cheese", "tomato", "onion", "cashew", "cream", "butter", "garlic", "ginger"], extraNeeded: ["kasuri methi"], instructions: ["Boil onion, tomato, cashews and garlic together for 10 minutes. Cool and blend smooth.", "Heat butter in a pan, add the blended sauce and cook until it thickens and butter separates.", "Add red chilli powder, coriander powder and salt. Cook 3 minutes.", "Add cream and stir well. Simmer on low heat 5 minutes.", "Add paneer cubes and gently mix. Simmer 3 minutes.", "Crush kasuri methi between palms and add. Serve with naan or rice."] },
  { name: "Aloo Paratha", cuisine: "Punjabi", time: "30 min", difficulty: "Easy", diet: ["vegetarian"], description: "Whole-wheat flatbreads stuffed with spiced mashed potato.", ingredients: ["potato", "wheat flour", "atta", "onion", "green chilli", "coriander", "cumin", "butter", "ghee"], extraNeeded: ["ajwain"], instructions: ["Boil potatoes, peel and mash. Mix with chopped onion, green chilli, coriander, cumin and salt.", "Knead wheat flour into a smooth dough. Rest 15 minutes.", "Divide dough into balls. Flatten one ball, place potato filling in centre, seal and roll gently.", "Cook on a hot tawa on medium heat. Apply ghee or butter on both sides.", "Cook until golden brown spots appear on both sides.", "Serve hot with curd, pickle and butter."] },
  { name: "Chole Bhature", cuisine: "North Indian", time: "50 min", difficulty: "Medium", diet: ["vegetarian"], description: "Spiced chickpea curry with deep-fried fluffy bread.", ingredients: ["chickpeas", "chole", "chana", "onion", "tomato", "garlic", "ginger", "maida", "flour"], extraNeeded: ["chole masala"], instructions: ["Soak chickpeas overnight and pressure cook until soft.", "Fry onions until deep brown. Add garlic, ginger, tomatoes and cook until masala forms.", "Add chole masala, salt and cooked chickpeas. Simmer 15 minutes.", "For bhature: knead maida with curd, oil and salt into soft dough. Rest 30 minutes.", "Roll into oval shapes and deep fry in hot oil until puffed and golden.", "Serve chole topped with onion rings alongside hot bhature."] },
  { name: "Chicken Biryani", cuisine: "Hyderabadi", time: "60 min", difficulty: "Hard", diet: ["non-veg", "gluten-free"], description: "Basmati layered with spiced chicken and saffron, slow-cooked dum style.", ingredients: ["chicken", "basmati rice", "rice", "onion", "tomato", "yogurt", "curd", "saffron", "ghee", "mint", "coriander"], extraNeeded: ["fried onion"], instructions: ["Marinate chicken in yogurt, spices, fried onions, mint and coriander for 2 hours.", "Parboil basmati rice with whole spices until 70% cooked. Drain.", "In a heavy pot, layer half the rice, then the marinated chicken, then remaining rice.", "Dissolve saffron in warm milk. Drizzle over the top layer along with ghee.", "Seal with foil or dough and cook on very low heat (dum) for 25-30 minutes.", "Open just before serving. Mix gently and serve with raita."] },
  { name: "Samosa", cuisine: "North Indian", time: "45 min", difficulty: "Medium", diet: ["vegetarian", "vegan"], description: "Crispy pastries stuffed with spiced potato and peas.", ingredients: ["potato", "pea", "maida", "flour", "onion", "green chilli", "cumin", "coriander"], extraNeeded: ["ajwain", "mango powder"], instructions: ["Make a stiff dough with maida, ajwain, oil and water. Rest 30 minutes.", "Boil potatoes, mash coarsely. Add peas, onion, green chilli, cumin, coriander, amchur and salt.", "Divide dough into balls. Roll each into an oval and cut in half.", "Form a cone from each half, fill with potato mixture and seal edges firmly.", "Deep fry in medium-hot oil until golden and crispy, turning occasionally.", "Serve hot with green chutney and tamarind chutney."] },
  { name: "Rasam", cuisine: "South Indian", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Thin peppery tangy lentil broth with tomatoes and tamarind.", ingredients: ["toor dal", "lentil", "tomato", "tamarind", "pepper", "cumin", "garlic", "mustard seeds"], extraNeeded: ["curry leaves"], instructions: ["Pressure cook toor dal with turmeric. Mash well and add water to thin it out.", "Extract tamarind juice from soaked tamarind. Add to dal along with chopped tomatoes.", "Crush garlic, pepper and cumin coarsely. Add to the pot.", "Bring to a boil on medium heat. Simmer 8-10 minutes.", "Temper mustard seeds and curry leaves in ghee. Pour over rasam.", "Serve as a soup or over rice."] },
  { name: "Upma", cuisine: "South Indian", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "vegan"], description: "Savoury semolina porridge tempered with mustard seeds and curry leaves.", ingredients: ["semolina", "rava", "onion", "green chilli", "mustard seeds", "curry leaves", "ginger", "carrot"], extraNeeded: ["lemon"], instructions: ["Dry roast semolina in a pan on medium heat until fragrant and lightly golden. Set aside.", "Heat oil, splutter mustard seeds. Add urad dal, curry leaves, green chilli and ginger.", "Add onions and fry until translucent. Add carrot and cook 2 minutes.", "Add 2 cups boiling water for each cup of semolina. Add salt.", "Add roasted semolina while stirring continuously to avoid lumps.", "Cover and cook 3-4 minutes. Squeeze lemon juice, mix and serve."] },
  { name: "Poha", cuisine: "Maharashtra", time: "15 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Flattened rice with turmeric, onion and peanuts tempered with curry leaves.", ingredients: ["poha", "flattened rice", "beaten rice", "onion", "peanut", "mustard seeds", "turmeric", "curry leaves"], extraNeeded: ["lemon"], instructions: ["Rinse poha under water in a colander until soft. Drain completely.", "Add turmeric and salt to soaked poha. Mix gently.", "Heat oil, fry peanuts until crispy. Remove and set aside.", "In same oil, splutter mustard seeds. Add curry leaves, onion, green chilli and cook 3 minutes.", "Add poha and toss gently on medium heat for 3-4 minutes.", "Squeeze lemon, add peanuts, garnish with coriander and serve."] },
  { name: "Egg Curry", cuisine: "Indian", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Boiled eggs in a rich onion-tomato masala.", ingredients: ["egg", "onion", "tomato", "garlic", "ginger", "turmeric", "red chilli", "coriander"], extraNeeded: ["garam masala"], instructions: ["Boil eggs for 10 minutes. Peel and make small slits on surface.", "Fry onions in oil until deep golden. Add garlic and ginger, cook 2 minutes.", "Add tomatoes, turmeric, red chilli and coriander powder. Cook until oil separates.", "Add water to make a medium gravy. Bring to a boil.", "Add eggs and simmer 8-10 minutes. Add garam masala.", "Serve with rice or roti."] },
  { name: "Banana Halwa", cuisine: "South Indian", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Ripe bananas cooked with ghee, jaggery and cardamom into a fudgy halwa.", ingredients: ["banana", "milk", "ghee", "jaggery", "sugar", "cardamom", "cashew"], extraNeeded: [], instructions: ["Mash ripe bananas until completely smooth with no lumps.", "Heat ghee in a heavy pan. Fry cashews until golden, set aside.", "Add mashed banana to the pan and cook on medium heat, stirring continuously.", "Add jaggery and milk. Continue stirring until mixture thickens.", "Add cardamom powder and cook until halwa leaves the sides of the pan.", "Garnish with fried cashews and serve warm."] },
  { name: "Vegetable Pulao", cuisine: "Indian", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Fragrant basmati with whole spices and mixed vegetables.", ingredients: ["rice", "basmati rice", "onion", "carrot", "pea", "potato", "cumin", "bay leaf", "ginger", "garlic"], extraNeeded: ["whole spices"], instructions: ["Wash and soak basmati rice for 20 minutes. Drain.", "Heat ghee or oil. Add bay leaf, cumin, cardamom and cloves. Let splutter.", "Add sliced onions and fry until golden. Add ginger-garlic paste.", "Add all vegetables and stir fry 3 minutes. Add drained rice and mix gently.", "Add hot water (1:1.5 ratio), salt and bring to a boil.", "Cover and cook on lowest heat for 12-15 minutes. Fluff with a fork and serve."] },
  { name: "Butter Chicken", cuisine: "North Indian", time: "45 min", difficulty: "Medium", diet: ["non-veg", "gluten-free"], description: "Tender chicken in a silky mildly spiced tomato-cream sauce.", ingredients: ["chicken", "tomato", "onion", "cream", "butter", "garlic", "ginger", "yogurt", "curd", "garam masala"], extraNeeded: ["kasuri methi"], instructions: ["Marinate chicken in yogurt, garlic, ginger, red chilli and garam masala for 1 hour.", "Grill or pan-fry chicken until cooked with slight char. Set aside.", "Blend tomatoes, onion and cashews to a smooth sauce.", "Heat butter, cook the sauce until it deepens in colour and butter separates.", "Add red chilli powder, garam masala, salt and cream. Simmer 10 minutes.", "Add grilled chicken, crushed kasuri methi. Simmer 5 minutes and serve."] },
  { name: "Pav Bhaji", cuisine: "Mumbai Street Food", time: "35 min", difficulty: "Easy", diet: ["vegetarian"], description: "Thick spiced vegetable mash with butter-toasted dinner rolls.", ingredients: ["potato", "tomato", "onion", "pea", "capsicum", "bell pepper", "carrot", "butter", "cauliflower"], extraNeeded: ["pav buns", "pav bhaji masala"], instructions: ["Boil potato, cauliflower, carrot and pea together until soft. Mash coarsely.", "Heat butter in a large flat pan. Add onions and fry until golden.", "Add capsicum and tomatoes. Cook until mushy. Add pav bhaji masala and salt.", "Add the mashed vegetables and mix everything together. Add water as needed.", "Mash and cook on medium heat for 10 minutes until thick and buttery.", "Toast pav buns with butter. Serve bhaji topped with raw onion, lemon and coriander."] },
  { name: "Masala Chai", cuisine: "Indian", time: "10 min", difficulty: "Easy", diet: ["vegetarian"], description: "Spiced milk tea simmered with ginger, cardamom and cloves.", ingredients: ["milk", "tea", "ginger", "cardamom", "sugar", "cinnamon", "cloves"], extraNeeded: ["pepper"], instructions: ["Crush ginger, cardamom, cinnamon and cloves lightly in a mortar.", "Add water to a saucepan with the crushed spices. Bring to a boil.", "Add tea leaves and boil for 2 minutes.", "Add milk and sugar. Bring to a full boil.", "Reduce heat and simmer 3-4 minutes until the tea is a rich golden colour.", "Strain into cups and serve piping hot."] },
  { name: "Khichdi", cuisine: "Indian", time: "25 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Rice and lentils cooked into a comforting porridge with turmeric and cumin.", ingredients: ["rice", "moong dal", "lentil", "dal", "turmeric", "cumin", "ginger", "onion"], extraNeeded: ["ghee", "asafoetida"], instructions: ["Wash rice and moong dal together. Soak 15 minutes.", "Heat ghee in a pressure cooker. Add cumin, asafoetida and ginger.", "Add onion and fry until soft. Add turmeric and salt.", "Add drained rice and dal. Stir to coat.", "Add 3.5 cups water. Pressure cook for 3 whistles.", "Open and stir well. Add a drizzle of ghee and serve with pickle and yogurt."] },
  { name: "Palak Paneer", cuisine: "North Indian", time: "35 min", difficulty: "Medium", diet: ["vegetarian", "gluten-free"], description: "Cottage cheese in a smooth vibrant spinach gravy.", ingredients: ["spinach", "palak", "paneer", "cottage cheese", "onion", "tomato", "garlic", "ginger", "cream"], extraNeeded: ["garam masala"], instructions: ["Blanch spinach in boiling water for 2 minutes. Transfer to ice cold water immediately.", "Blend blanched spinach to a smooth puree.", "Fry onions, garlic, ginger and tomatoes. Cool and blend to paste.", "Cook the onion-tomato paste in oil until oil separates. Add garam masala.", "Add spinach puree, salt and cream. Simmer 5 minutes.", "Add paneer cubes and cook 3 minutes. Do not overcook the spinach — it loses colour."] },
  { name: "Gulab Jamun", cuisine: "Indian Sweets", time: "40 min", difficulty: "Medium", diet: ["vegetarian"], description: "Soft spongy milk-solid dumplings soaked in rose-scented sugar syrup.", ingredients: ["milk powder", "khoya", "mawa", "maida", "flour", "ghee", "sugar", "cardamom"], extraNeeded: ["rose water"], instructions: ["Mix khoya, milk powder, maida, a pinch of baking soda and ghee. Knead gently.", "Add a little milk to make a soft dough. Do not over-knead. Rest 10 minutes.", "Make sugar syrup: boil sugar and water until slightly sticky. Add cardamom and rose water.", "Roll dough into smooth balls without cracks.", "Fry in medium-warm oil (not hot) slowly until deep brown — about 8-10 minutes.", "Soak hot jamuns in warm syrup for at least 30 minutes before serving."] },
  { name: "Veg Hakka Noodles", cuisine: "Indo-Chinese", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "vegan"], description: "Stir-fried noodles with colourful vegetables in soy and vinegar.", ingredients: ["noodles", "carrot", "cabbage", "onion", "capsicum", "bell pepper", "soy sauce", "garlic", "ginger"], extraNeeded: ["vinegar", "chilli sauce"], instructions: ["Boil noodles until al dente. Drain and toss with oil to prevent sticking.", "Heat oil in a wok on high heat. Add garlic and ginger, stir-fry 30 seconds.", "Add all vegetables and stir-fry on high heat for 3 minutes — keep them crunchy.", "Add soy sauce, vinegar, chilli sauce and salt. Toss well.", "Add noodles and toss everything together on high heat for 2 minutes.", "Serve immediately garnished with spring onions."] },
  { name: "Mutton Curry", cuisine: "Indian", time: "70 min", difficulty: "Hard", diet: ["non-veg", "gluten-free"], description: "Slow-cooked mutton in a deeply spiced onion-tomato gravy.", ingredients: ["mutton", "lamb", "onion", "tomato", "garlic", "ginger", "yogurt", "curd", "red chilli", "coriander"], extraNeeded: ["whole spices", "garam masala"], instructions: ["Marinate mutton in yogurt, garlic, ginger, red chilli and salt for 1 hour.", "Heat oil, add whole spices (bay leaf, cardamom, cloves). Add onions and fry until deep brown.", "Add marinated mutton and cook on high heat until browned on all sides.", "Add tomatoes and cook until oil separates.", "Add water, cover and cook on low heat for 45-50 minutes until mutton is tender.", "Add garam masala, simmer 5 minutes. Serve with rice or paratha."] },
  { name: "Mixed Vegetable Curry", cuisine: "Indian", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Seasonal vegetables simmered in a spiced tomato-onion gravy.", ingredients: ["potato", "carrot", "pea", "tomato", "onion", "garlic", "ginger", "turmeric", "red chilli", "coriander"], extraNeeded: ["garam masala"], instructions: ["Chop all vegetables into even-sized pieces.", "Fry onions in oil until golden. Add garlic and ginger, cook 2 minutes.", "Add tomatoes, turmeric, red chilli and coriander powder. Cook until oil separates.", "Add all vegetables and stir to coat in the masala.", "Add water, cover and cook 15-20 minutes until vegetables are tender.", "Add garam masala and fresh coriander. Serve with roti."] },
  { name: "Curd Rice", cuisine: "South Indian", time: "15 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Cooked rice mixed with fresh yogurt and tempered with mustard seeds.", ingredients: ["rice", "curd", "yogurt", "mustard seeds", "ginger", "green chilli", "curry leaves"], extraNeeded: ["pomegranate"], instructions: ["Cook rice until slightly overcooked and mushy. Cool to room temperature.", "Mash rice slightly and mix with yogurt and milk. Add salt.", "Heat oil, splutter mustard seeds. Add urad dal, dried red chilli, green chilli, ginger and curry leaves.", "Pour hot tempering over the rice-curd mixture and mix well.", "Garnish with pomegranate seeds and grated carrot.", "Serve chilled or at room temperature as a comforting meal."] },
  { name: "Tomato Rice", cuisine: "South Indian", time: "25 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Tangy spiced rice with fresh tomatoes tempered with curry leaves.", ingredients: ["rice", "tomato", "onion", "mustard seeds", "curry leaves", "red chilli", "turmeric", "garlic"], extraNeeded: ["sambar powder"], instructions: ["Cook rice and spread on a plate to cool.", "Heat oil, splutter mustard seeds. Add urad dal, curry leaves and dried red chilli.", "Add onions and fry until golden. Add garlic and cook 1 minute.", "Add tomatoes, turmeric and sambar powder. Cook until tomatoes are fully mushy and oil separates.", "Add cooked rice and toss gently to coat with the masala.", "Serve with papad and pickle."] },
  { name: "Aloo Gobi", cuisine: "North Indian", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Dry-style potato and cauliflower stir-fried with cumin and turmeric.", ingredients: ["potato", "cauliflower", "onion", "tomato", "garlic", "ginger", "cumin", "turmeric", "coriander"], extraNeeded: ["garam masala"], instructions: ["Cut potato and cauliflower into equal sized florets and pieces.", "Heat oil, add cumin seeds. Add onion and fry until golden.", "Add garlic, ginger and tomatoes. Cook until mushy.", "Add turmeric, coriander powder and salt. Cook 2 minutes.", "Add potato and cauliflower. Mix well and cook covered on low heat for 15 minutes.", "Add garam masala, garnish with coriander and serve dry with roti."] },
  { name: "Baingan Bharta", cuisine: "North Indian", time: "35 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Smoky fire-roasted aubergine mashed with onion and spices.", ingredients: ["brinjal", "eggplant", "aubergine", "onion", "tomato", "garlic", "ginger", "green chilli", "coriander"], extraNeeded: ["garam masala"], instructions: ["Roast the whole brinjal directly on a gas flame, turning until charred all over.", "Cool, peel off the charred skin and mash the flesh with garlic.", "Fry onions in oil until golden. Add ginger, green chilli and cook 2 minutes.", "Add tomatoes and cook until oil separates.", "Add the mashed brinjal, salt and garam masala. Mix and cook 5 minutes.", "Garnish with coriander. Serve with roti."] },
  { name: "Methi Thepla", cuisine: "Gujarati", time: "25 min", difficulty: "Easy", diet: ["vegetarian", "vegan"], description: "Soft flatbreads with fresh fenugreek leaves and spices.", ingredients: ["wheat flour", "atta", "fenugreek leaves", "methi", "yogurt", "curd", "turmeric", "cumin", "green chilli"], extraNeeded: ["sesame seeds"], instructions: ["Wash and finely chop fresh methi leaves. Sprinkle salt and rest 5 minutes, then squeeze out water.", "Mix with wheat flour, turmeric, cumin, green chilli, sesame seeds and yogurt.", "Knead into a smooth, slightly stiff dough. Add oil and knead again.", "Divide into balls and roll into thin circles.", "Cook on a hot tawa with a little oil on each side until golden brown spots appear.", "Serve with yogurt, pickle or green chutney."] },
  { name: "Matar Paneer", cuisine: "North Indian", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Cottage cheese and green peas in a spiced tomato-onion gravy.", ingredients: ["paneer", "cottage cheese", "pea", "tomato", "onion", "garlic", "ginger", "turmeric", "red chilli"], extraNeeded: ["garam masala"], instructions: ["Fry onions in oil until golden. Add garlic and ginger, cook 2 minutes.", "Blend tomatoes to a puree and add to the pan. Cook until oil separates.", "Add turmeric, red chilli and coriander powder. Cook 3 minutes.", "Add peas and water. Simmer 8 minutes until peas are soft.", "Add paneer cubes and garam masala. Simmer 4 minutes.", "Serve with roti or rice."] },
  { name: "Saag Aloo", cuisine: "North Indian", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Tender potatoes in a vibrant spiced spinach gravy.", ingredients: ["potato", "spinach", "palak", "onion", "garlic", "ginger", "cumin", "turmeric", "green chilli"], extraNeeded: ["garam masala"], instructions: ["Blanch spinach briefly, blend to a rough puree.", "Boil or fry potatoes until half cooked.", "Heat oil, add cumin. Add onion, garlic, ginger and fry until golden.", "Add turmeric, green chilli and cook 1 minute.", "Add spinach puree and potatoes. Simmer 10 minutes until potatoes are cooked through.", "Add garam masala and salt. Serve with roti."] },
  { name: "Chana Masala", cuisine: "North Indian", time: "40 min", difficulty: "Medium", diet: ["vegetarian", "vegan", "gluten-free"], description: "Hearty chickpeas in a robust tangy tomato-onion masala.", ingredients: ["chickpeas", "chana", "chole", "onion", "tomato", "garlic", "ginger", "cumin", "turmeric", "red chilli"], extraNeeded: ["amchur", "chana masala powder"], instructions: ["Soak chickpeas overnight. Pressure cook until tender (4-5 whistles).", "Fry onions until deep brown. Add garlic, ginger and cook 2 minutes.", "Add tomatoes and cook until oil separates completely.", "Add all spice powders including chana masala and amchur. Cook 3 minutes.", "Add chickpeas with some cooking water. Simmer 15 minutes.", "Serve topped with raw onion, lemon and coriander with bhature or rice."] },
  { name: "Rava Idli", cuisine: "South Indian", time: "25 min", difficulty: "Easy", diet: ["vegetarian"], description: "Instant semolina idlis — fluffy, no-ferment steamed cakes.", ingredients: ["semolina", "rava", "curd", "yogurt", "mustard seeds", "curry leaves", "green chilli", "ginger", "carrot"], extraNeeded: ["eno fruit salt"], instructions: ["Dry roast semolina until fragrant. Cool completely.", "Mix with curd, chopped green chilli, grated ginger, grated carrot and salt.", "Rest the batter for 10 minutes. Add water if needed to get a thick pourable consistency.", "Add eno fruit salt just before steaming and mix gently.", "Pour into greased idli moulds and steam for 12-15 minutes.", "Rest 2 minutes, unmould and serve with coconut chutney and sambar."] },
  { name: "Pesarattu", cuisine: "Andhra", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Crispy green moong dal crepes — high protein Andhra breakfast.", ingredients: ["moong dal", "green moong", "lentil", "ginger", "green chilli", "onion", "cumin", "rice"], extraNeeded: ["ginger chutney"], instructions: ["Soak green moong dal for 4-6 hours. Drain.", "Blend with rice, ginger, green chilli, cumin and water to a smooth batter.", "Rest batter 15 minutes. Add salt.", "Heat a dosa pan, pour batter and spread into a thin circle.", "Top with finely chopped onion, ginger and green chilli.", "Drizzle oil on edges, cook until crispy underneath. Fold and serve with ginger chutney."] },
  { name: "Beetroot Halwa", cuisine: "Indian Sweets", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Grated beetroot slow-cooked in milk with ghee, sugar and cardamom.", ingredients: ["beetroot", "milk", "ghee", "sugar", "cardamom", "cashew"], extraNeeded: ["khoya"], instructions: ["Peel and grate beetroot finely.", "Heat ghee in a heavy pan. Fry cashews until golden, set aside.", "Add grated beetroot and cook on medium heat for 8 minutes until it softens.", "Add milk and cook until milk is almost absorbed, stirring frequently.", "Add sugar and khoya. Cook until mixture thickens and leaves the pan sides.", "Add cardamom, garnish with cashews and serve warm."] },
  { name: "Paneer Tikka", cuisine: "North Indian", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Marinated cottage cheese grilled until charred and smoky.", ingredients: ["paneer", "cottage cheese", "yogurt", "curd", "garlic", "ginger", "red chilli", "turmeric", "capsicum", "bell pepper", "onion"], extraNeeded: ["tandoori masala", "lemon"], instructions: ["Cut paneer into 1.5-inch cubes. Cut capsicum and onion into similar sized pieces.", "Mix yogurt, tandoori masala, garlic paste, ginger paste, red chilli, turmeric, lemon juice and salt.", "Add paneer and vegetables to marinade. Toss well and rest for at least 30 minutes.", "Thread onto skewers alternating paneer and vegetables.", "Grill on high heat or in oven at 220°C for 15-20 minutes until charred.", "Serve with mint chutney, sliced onions and lemon."] },
  { name: "Sooji Halwa", cuisine: "Indian Sweets", time: "20 min", difficulty: "Easy", diet: ["vegetarian"], description: "Golden semolina roasted in ghee with sugar and cardamom.", ingredients: ["semolina", "rava", "ghee", "sugar", "milk", "cardamom", "cashew"], extraNeeded: ["saffron", "raisins"], instructions: ["Heat ghee in a heavy pan. Fry cashews and raisins until golden. Remove and set aside.", "Add semolina to the same ghee and roast on medium heat until golden and aromatic, about 8 minutes.", "In a separate pan, heat milk and water together until warm.", "Carefully pour the warm liquid into the semolina while stirring (it will splutter).", "Add sugar and stir continuously until mixture thickens and leaves the pan.", "Add cardamom, saffron, fried cashews and raisins. Serve warm."] },
  { name: "Veg Manchurian", cuisine: "Indo-Chinese", time: "35 min", difficulty: "Medium", diet: ["vegetarian", "vegan"], description: "Crispy veggie balls in a tangy-spicy Indo-Chinese sauce.", ingredients: ["cabbage", "carrot", "onion", "garlic", "ginger", "maida", "flour", "soy sauce", "green chilli", "spring onion"], extraNeeded: ["corn starch", "chilli sauce"], instructions: ["Grate cabbage and carrot finely. Mix with flour, corn starch, garlic, ginger, soy sauce and salt.", "Shape into small balls. Deep fry until golden and crispy. Set aside.", "For sauce: heat oil, add garlic, ginger and green chilli. Stir-fry 30 seconds.", "Add soy sauce, chilli sauce, vinegar and a cornstarch slurry. Bring to a boil.", "Add fried balls to the sauce and toss to coat.", "Garnish with spring onions and serve hot."] },
  { name: "Kadhi Pakora", cuisine: "Punjabi", time: "45 min", difficulty: "Medium", diet: ["vegetarian", "gluten-free"], description: "Crispy gram flour fritters in a tangy yogurt-besan curry.", ingredients: ["besan", "gram flour", "yogurt", "curd", "onion", "green chilli", "ginger", "cumin", "turmeric", "mustard seeds"], extraNeeded: ["curry leaves", "red chilli"], instructions: ["For pakoras: mix besan, onion, green chilli, ginger and salt with water to thick batter. Deep fry spoonfuls until golden.", "For kadhi: whisk together yogurt, besan, turmeric and water until smooth.", "Heat ghee, add mustard seeds, cumin and dried red chilli.", "Add the yogurt-besan mixture and cook on medium heat, stirring constantly for 10 minutes.", "Once kadhi thickens, add pakoras and simmer 10 minutes.", "Finish with a red chilli-ghee tadka. Serve with steamed rice."] },
  { name: "Pongal", cuisine: "South Indian", time: "25 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Creamy rice and moong dal cooked with pepper, cumin and ghee.", ingredients: ["rice", "moong dal", "lentil", "ghee", "pepper", "cumin", "ginger", "cashew"], extraNeeded: ["curry leaves", "asafoetida"], instructions: ["Wash rice and moong dal together.", "Heat ghee in a pressure cooker. Add cumin, pepper and asafoetida.", "Add rice and dal, stir briefly. Add 3.5 cups water and salt.", "Pressure cook for 4 whistles until very soft and mushy.", "Mash gently. Heat more ghee, fry cashews and curry leaves.", "Pour cashew tempering over pongal and serve with sambar and chutney."] },
  { name: "Aloo Matar", cuisine: "North Indian", time: "25 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "A simple everyday curry of potatoes and green peas.", ingredients: ["potato", "pea", "tomato", "onion", "garlic", "ginger", "cumin", "turmeric", "coriander"], extraNeeded: ["garam masala"], instructions: ["Dice potatoes and boil until 80% cooked.", "Fry onions until golden. Add garlic, ginger and cook 2 minutes.", "Add tomatoes, turmeric, coriander powder and salt. Cook until oil separates.", "Add potatoes and peas. Mix well.", "Add water, cover and simmer 12 minutes until potatoes are fully cooked.", "Add garam masala and coriander leaves. Serve with roti."] },
  { name: "Moong Dal Cheela", cuisine: "North Indian", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Thin savoury pancakes made from soaked moong dal.", ingredients: ["moong dal", "lentil", "onion", "green chilli", "ginger", "coriander", "turmeric", "cumin"], extraNeeded: ["oil"], instructions: ["Soak moong dal for 2 hours. Blend with ginger and a little water to a smooth batter.", "Add chopped onion, green chilli, coriander, cumin, turmeric and salt to the batter.", "Heat a non-stick pan, pour a ladleful of batter and spread into a thin circle.", "Drizzle oil on the sides and cook on medium heat until edges brown.", "Flip and cook the other side for 2 minutes.", "Serve hot with green chutney or yogurt."] },
  { name: "Lauki Kofta", cuisine: "North Indian", time: "40 min", difficulty: "Medium", diet: ["vegetarian"], description: "Soft bottle gourd dumplings in a creamy spiced tomato gravy.", ingredients: ["bottle gourd", "lauki", "besan", "gram flour", "onion", "tomato", "garlic", "ginger", "yogurt", "curd"], extraNeeded: ["garam masala", "cream"], instructions: ["Grate lauki, squeeze out excess water. Mix with besan, green chilli, ginger, salt and make koftas.", "Deep fry koftas until golden. Set aside.", "For gravy: blend onion, tomato and garlic. Cook in oil until oil separates.", "Add yogurt, all spice powders and cook 5 minutes.", "Add water to get a medium gravy. Simmer 8 minutes.", "Add koftas just before serving. Top with cream and garam masala."] },
  { name: "Stuffed Capsicum", cuisine: "Indian", time: "35 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Bell peppers stuffed with spiced potato and pea filling.", ingredients: ["capsicum", "bell pepper", "potato", "pea", "onion", "tomato", "garlic", "cumin", "coriander", "turmeric"], extraNeeded: ["garam masala"], instructions: ["Cut tops off capsicums and remove seeds to make hollow cups.", "Boil potatoes and mash. Mix with peas, onion, green chilli, cumin, coriander and salt.", "Fill capsicums tightly with the potato mixture.", "Heat oil in a pan, place stuffed capsicums upright. Cover and cook on low heat 10 minutes.", "Rotate gently and cook until capsicum is soft and slightly charred.", "Serve with roti or as a side dish."] },
  { name: "Vermicelli Upma", cuisine: "South Indian", time: "15 min", difficulty: "Easy", diet: ["vegetarian"], description: "Roasted vermicelli tossed with vegetables and mustard seeds.", ingredients: ["vermicelli", "seviyan", "onion", "carrot", "pea", "green chilli", "mustard seeds", "curry leaves", "ginger"], extraNeeded: ["lemon"], instructions: ["Dry roast vermicelli until golden brown. Set aside.", "Heat oil, splutter mustard seeds. Add curry leaves, green chilli and ginger.", "Add onion and fry until translucent. Add carrot and peas.", "Add 1.5 cups boiling water per cup of vermicelli. Add salt.", "Add roasted vermicelli and stir. Cover and cook 5 minutes until water is absorbed.", "Squeeze lemon, fluff gently and serve hot."] },
  { name: "Coconut Rice", cuisine: "South Indian", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Fragrant rice tossed with fresh grated coconut and mustard seeds.", ingredients: ["rice", "coconut", "mustard seeds", "curry leaves", "red chilli", "urad dal", "chana dal", "ginger"], extraNeeded: ["cashew"], instructions: ["Cook rice and spread to cool. Each grain should be separate.", "Heat oil, fry cashews until golden. Remove and set aside.", "In the same oil, splutter mustard seeds. Add urad dal and chana dal and fry until golden.", "Add dried red chilli, curry leaves and grated ginger.", "Add grated coconut and stir fry for 2 minutes on low heat.", "Add rice, salt and toss gently. Garnish with cashews and serve."] },
  // ── Karnataka Vegetarian ──
  { name: "Bisi Bele Bath", cuisine: "Karnataka", time: "50 min", difficulty: "Medium", diet: ["vegetarian", "gluten-free"], description: "Karnataka's soul food — piping hot one-pot of rice, lentils and vegetables.", ingredients: ["rice", "toor dal", "lentil", "onion", "tomato", "potato", "carrot", "pea", "tamarind", "ghee", "turmeric"], extraNeeded: ["bisi bele bath powder", "curry leaves"], instructions: ["Dry roast and grind bisi bele bath powder (if making fresh) with coconut, spices and dry chillies.", "Cook rice and toor dal together with 3x water until mushy.", "Add chopped vegetables, tamarind extract, bisi bele bath powder and salt.", "Cook on low heat 20 minutes, stirring frequently to prevent sticking.", "Adjust consistency with water — it should be thick and porridge-like.", "Finish with a generous pour of ghee and a mustard-cashew tempering. Serve hot."] },
  { name: "Jolada Rotti", cuisine: "North Karnataka", time: "30 min", difficulty: "Medium", diet: ["vegetarian", "vegan", "gluten-free"], description: "Thick unleavened jowar flatbread — North Karnataka staple.", ingredients: ["jowar flour", "sorghum flour", "water", "salt"], extraNeeded: ["oil"], instructions: ["Bring water to a boil. Add salt.", "Slowly add jowar flour to the boiling water, stirring constantly until a thick dough forms.", "Remove from heat and knead while hot (use a wet cloth to protect hands).", "Divide into balls. Pat into thick rounds directly on a flat surface using wet palms.", "Cook on a dry hot tawa on both sides until cooked through with brown spots.", "Serve immediately with ennegayi, chutney or curd."] },
  { name: "Ennegayi", cuisine: "North Karnataka", time: "35 min", difficulty: "Medium", diet: ["vegetarian", "vegan", "gluten-free"], description: "Brinjals stuffed with peanut-sesame-coconut masala — a Dharwad classic.", ingredients: ["brinjal", "eggplant", "peanut", "sesame seeds", "coconut", "onion", "garlic", "red chilli", "tamarind", "coriander"], extraNeeded: ["jaggery"], instructions: ["Dry roast peanuts and sesame seeds separately until golden. Cool.", "Grind roasted peanuts, sesame, coconut, garlic, red chilli, tamarind and jaggery into a coarse masala.", "Slit small brinjals into quarters without cutting through the stem.", "Stuff masala generously into each brinjal.", "Heat oil in a heavy pan. Place stuffed brinjals and cook covered on low heat.", "Turn gently every 5 minutes until brinjals are fully cooked and masala is fragrant."] },
  { name: "Huuli", cuisine: "Karnataka", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Light tangy Karnataka dal made with toor dal, tamarind and coconut.", ingredients: ["toor dal", "lentil", "tamarind", "coconut", "tomato", "onion", "mustard seeds", "curry leaves", "turmeric"], extraNeeded: ["jaggery"], instructions: ["Pressure cook toor dal until soft. Mash well.", "Grind fresh coconut with a little water to a smooth paste.", "Add tamarind extract, tomato, onion and coconut paste to the dal.", "Bring to a boil, add turmeric, jaggery and salt. Simmer 10 minutes.", "Temper mustard seeds and curry leaves in oil. Pour over the huuli.", "Serve with rice. It should be tangier and thinner than sambar."] },
  { name: "Akki Rotti", cuisine: "Karnataka", time: "25 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Rice flour flatbread packed with onion, coconut and curry leaves.", ingredients: ["rice flour", "onion", "coconut", "green chilli", "curry leaves", "coriander", "cumin", "ginger"], extraNeeded: ["oil"], instructions: ["Mix rice flour, finely chopped onion, grated coconut, green chilli, ginger, curry leaves, coriander and cumin.", "Add hot water gradually and knead into a soft pliable dough.", "Wet a banana leaf or plastic sheet. Place a portion of dough and pat with wet palms into a thin circle.", "Transfer to a hot tawa greased with oil.", "Cook on medium heat until the edges start to leave the pan. Flip and cook until done.", "Serve with coconut chutney or pickle."] },
  { name: "Chitranna", cuisine: "Karnataka", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Karnataka lemon rice with turmeric, mustard seeds and peanuts.", ingredients: ["rice", "lemon", "peanut", "mustard seeds", "curry leaves", "green chilli", "turmeric", "urad dal", "chana dal"], extraNeeded: ["asafoetida"], instructions: ["Cook rice and cool completely. Each grain should be separate.", "Heat oil, fry peanuts until golden. Remove.", "In same oil, splutter mustard seeds. Add urad dal, chana dal and fry until golden.", "Add asafoetida, curry leaves, green chilli and turmeric.", "Add cold rice and toss to coat evenly.", "Squeeze generous lemon juice, add peanuts, adjust salt and serve."] },
  { name: "Vangi Bath", cuisine: "Karnataka", time: "35 min", difficulty: "Medium", diet: ["vegetarian", "vegan", "gluten-free"], description: "Brinjal rice with vangi bath masala and peanuts.", ingredients: ["rice", "brinjal", "eggplant", "onion", "tomato", "peanut", "mustard seeds", "curry leaves", "tamarind", "turmeric"], extraNeeded: ["vangi bath powder"], instructions: ["Cook rice and spread to cool.", "Cut brinjal into pieces and soak in salted water to prevent browning.", "Heat oil, fry peanuts until golden. Add mustard seeds and curry leaves.", "Add onion and fry until golden. Add brinjal and cook until soft.", "Add tomato, tamarind extract, vangi bath powder and turmeric. Cook 5 minutes.", "Add cooked rice, toss gently and simmer 3 minutes. Serve with raita."] },
  { name: "Kosambari", cuisine: "Karnataka", time: "15 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Light soaked moong dal salad with cucumber and coconut.", ingredients: ["moong dal", "lentil", "cucumber", "coconut", "coriander", "green chilli", "lemon", "mustard seeds"], extraNeeded: ["asafoetida"], instructions: ["Soak moong dal for 1-2 hours. Drain completely.", "Peel and finely dice cucumber. Remove excess water.", "Mix moong dal, cucumber, grated coconut, chopped coriander and green chilli.", "Add lemon juice and salt. Toss well.", "Heat oil, splutter mustard seeds with a pinch of asafoetida. Pour over salad.", "Mix and serve immediately as a side dish."] },
  { name: "Ragi Mudde", cuisine: "Karnataka", time: "15 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Dense finger millet balls — a nutritious Karnataka staple eaten with saaru.", ingredients: ["ragi flour", "finger millet flour", "water", "salt"], extraNeeded: [], instructions: ["Bring 2 cups water to a rolling boil in a heavy pan.", "Add salt. Add 2 tablespoons of ragi flour and stir quickly.", "Reduce heat. Add the remaining flour all at once.", "Cover and cook on low heat for 5 minutes without stirring.", "Stir vigorously with a wooden spoon until fully cooked and a smooth ball forms.", "Wet hands, shape into smooth balls and serve immediately with saaru and ghee."] },
  { name: "Obbattu", cuisine: "Karnataka", time: "45 min", difficulty: "Medium", diet: ["vegetarian"], description: "Sweet flatbread stuffed with chana dal and jaggery — Karnataka's festival sweet.", ingredients: ["chana dal", "lentil", "jaggery", "maida", "flour", "turmeric", "cardamom", "ghee"], extraNeeded: ["oil"], instructions: ["Cook chana dal until soft. Drain and grind with jaggery and cardamom to a smooth paste (puran).", "Knead maida with oil, turmeric and water into a very soft, elastic dough. Rest 30 minutes.", "Take a small dough ball, flatten, place a filling ball in the centre and seal tightly.", "Roll gently into a thin circle using a rolling pin.", "Cook on a medium-hot tawa with a little ghee, pressing gently.", "Cook both sides until golden spots appear. Serve warm with ghee and milk."] },
  // ── Karnataka Non-Veg ──
  { name: "Nati Koli Saaru", cuisine: "Karnataka", time: "60 min", difficulty: "Hard", diet: ["non-veg", "gluten-free"], description: "Country chicken curry with freshly ground Karnataka masala and coconut.", ingredients: ["chicken", "country chicken", "coconut", "onion", "tomato", "garlic", "ginger", "red chilli", "coriander", "pepper"], extraNeeded: ["curry leaves", "jaggery"], instructions: ["Grind coconut, red chillies, coriander, pepper and garlic into a fresh masala paste.", "Marinate country chicken with turmeric and salt for 30 minutes.", "Fry onions in oil until deep brown. Add tomatoes and cook until mushy.", "Add the ground masala and cook until oil separates.", "Add chicken pieces and cook on high heat for 10 minutes.", "Add water, jaggery and simmer 30-40 minutes until country chicken is tender. Finish with curry leaves."] },
  { name: "Coorg Pandi Curry", cuisine: "Coorg", time: "70 min", difficulty: "Hard", diet: ["non-veg", "gluten-free"], description: "Coorgi pork curry cooked with kachampuli — dark, smoky and iconic.", ingredients: ["pork", "onion", "garlic", "ginger", "red chilli", "pepper", "coriander", "turmeric", "cinnamon", "cloves"], extraNeeded: ["kachampuli", "kachampuli vinegar"], instructions: ["Cut pork into pieces. Marinate with turmeric, salt and half the spices for 1 hour.", "Heat oil in a heavy pot. Fry onions until very dark brown.", "Add garlic, ginger and cook 3 minutes. Add all ground spices.", "Add marinated pork and sear on high heat until browned.", "Add kachampuli (Coorg vinegar) and water. Cover and cook on low heat for 45-50 minutes.", "The curry should be dark, thick and intensely flavoured. Serve with rice or akki rotti."] },
  { name: "Mangalore Chicken Curry", cuisine: "Mangalorean", time: "45 min", difficulty: "Medium", diet: ["non-veg", "gluten-free"], description: "Coastal chicken curry with roasted coconut masala and bedgi chillies.", ingredients: ["chicken", "coconut", "onion", "tomato", "red chilli", "garlic", "ginger", "turmeric", "tamarind", "coriander"], extraNeeded: ["curry leaves"], instructions: ["Roast coconut until golden. Dry roast red chillies and coriander seeds.", "Grind roasted coconut, chillies, coriander with garlic, ginger and tamarind to a smooth paste.", "Fry onions in oil until golden. Add the ground masala paste.", "Cook masala until oil separates and it darkens. Add tomatoes.", "Add chicken pieces and cook on high heat 8 minutes. Add water and simmer 20 minutes.", "Finish with curry leaves. Serve with neer dosa or rice."] },
  { name: "Yetti Gassi", cuisine: "Coastal Karnataka", time: "35 min", difficulty: "Medium", diet: ["non-veg", "gluten-free"], description: "Prawn curry in a rich roasted coconut masala with kokum.", ingredients: ["prawns", "shrimp", "coconut", "onion", "red chilli", "garlic", "turmeric", "tamarind", "coriander"], extraNeeded: ["kokum", "curry leaves"], instructions: ["Dry roast coconut until brown. Roast red chillies and coriander.", "Grind roasted coconut, chillies, coriander, garlic with tamarind to a smooth paste.", "Fry onions in oil until golden. Add the masala paste and cook until oil separates.", "Add kokum pieces and water. Bring to a boil.", "Add cleaned prawns and cook on medium heat for 6-8 minutes. Do not overcook.", "Finish with curry leaves. Serve with rice or neer dosa."] },
  { name: "Chicken Sukka", cuisine: "Mangalorean", time: "45 min", difficulty: "Medium", diet: ["non-veg", "gluten-free"], description: "Dry-style chicken with roasted coconut and spices.", ingredients: ["chicken", "coconut", "onion", "garlic", "ginger", "red chilli", "pepper", "turmeric", "coriander"], extraNeeded: ["curry leaves", "fennel seeds"], instructions: ["Dry roast coconut until golden brown. Roast red chillies, coriander and fennel seeds.", "Grind into a coarse masala. Do not make it too smooth.", "Fry onions in coconut oil until dark golden. Add garlic, ginger and cook 2 minutes.", "Add chicken and cook on high heat until browned and moisture evaporates.", "Add the ground masala, turmeric and salt. Mix well.", "Cook on low heat until completely dry and masala coats chicken. Finish with curry leaves."] },
  { name: "Fish Gassi", cuisine: "Tulu Nadu", time: "35 min", difficulty: "Medium", diet: ["non-veg", "gluten-free"], description: "Classic Tulu Nadu fish curry in a red coconut masala with kokum.", ingredients: ["fish", "coconut", "onion", "red chilli", "garlic", "turmeric", "tamarind", "coriander"], extraNeeded: ["kokum", "curry leaves"], instructions: ["Roast coconut until golden. Dry roast red chillies.", "Grind with garlic, coriander seeds and tamarind to a very smooth paste.", "Fry onions in coconut oil until golden. Add ground masala paste.", "Cook on medium heat until oil separates and masala darkens.", "Add kokum, water and bring to a boil. Add fish pieces gently.", "Simmer 10-12 minutes. Do not stir — swirl the pan gently. Finish with curry leaves."] },
  // ── Sattvic ──
  { name: "Sabudana Khichdi", cuisine: "Sattvic", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Tapioca pearls cooked with peanuts and cumin — light sattvic dish.", ingredients: ["sabudana", "tapioca", "peanut", "potato", "cumin", "green chilli", "ghee", "lemon"], extraNeeded: ["coriander"], instructions: ["Wash sabudana and soak for 4-6 hours until soft. Drain thoroughly.", "Roast peanuts and coarsely crush them. Mix with soaked sabudana and salt.", "Heat ghee in a pan. Add cumin seeds and let them splutter.", "Add diced potato and cook until golden. Add green chilli.", "Add sabudana-peanut mixture and toss gently on medium heat for 5-7 minutes.", "Squeeze lemon, garnish with coriander and serve hot."] },
  { name: "Fruit Chaat", cuisine: "Sattvic", time: "10 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Refreshing seasonal fruits with lemon, rock salt and mint.", ingredients: ["apple", "banana", "pomegranate", "grapes", "orange", "lemon", "mint", "honey"], extraNeeded: ["rock salt"], instructions: ["Wash and chop all fruits into bite-sized pieces.", "Remove pomegranate seeds and de-seed grapes if needed.", "Combine all fruits in a bowl.", "Add lemon juice, honey, a pinch of rock salt and chaat masala.", "Tear fresh mint leaves and add.", "Toss gently and serve chilled."] },
  { name: "Moong Dal Payasam", cuisine: "Karnataka Sattvic", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Roasted moong dal in coconut milk and jaggery — Karnataka festival sweet.", ingredients: ["moong dal", "lentil", "coconut milk", "coconut", "jaggery", "cardamom", "ghee", "cashew"], extraNeeded: ["raisins"], instructions: ["Dry roast moong dal until golden brown and fragrant.", "Pressure cook roasted moong dal until soft and slightly mushy.", "Dissolve jaggery in a little water and strain to remove impurities.", "Add jaggery syrup to cooked moong dal. Simmer on low heat 5 minutes.", "Add coconut milk and cardamom. Heat gently — do not boil after adding coconut milk.", "Heat ghee and fry cashews and raisins. Pour over payasam and serve."] },
  { name: "Thambittu", cuisine: "Karnataka Sattvic", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Roasted rice flour and jaggery sweet — traditional Karnataka festival offering.", ingredients: ["rice flour", "jaggery", "coconut", "cardamom", "ghee", "sesame seeds"], extraNeeded: [], instructions: ["Dry roast rice flour on low heat until it turns slightly golden and smells nutty. Cool completely.", "Dissolve jaggery in minimal water and strain.", "Mix roasted rice flour with grated coconut and roasted sesame seeds.", "Add jaggery syrup gradually and mix until the mixture holds its shape.", "Add cardamom powder and a spoon of melted ghee. Mix well.", "Shape into rounds or press into moulds. Serve as prasad or snack."] },
  // ── Juices ──
  { name: "Fresh Sugarcane Juice", cuisine: "Juice", time: "5 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Freshly pressed sugarcane juice with ginger and lemon.", ingredients: ["sugarcane", "ginger", "lemon", "mint"], extraNeeded: ["ice"], instructions: ["Feed sugarcane stalks through a sugarcane press or juicer to extract juice.", "Add a small piece of ginger and press again to blend flavours.", "Strain the juice to remove any fibre.", "Squeeze fresh lemon juice into the glass.", "Add a few mint leaves and crushed ice.", "Serve immediately — sugarcane juice oxidises quickly."] },
  { name: "Watermelon Juice", cuisine: "Juice", time: "5 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Chilled watermelon with mint and black salt.", ingredients: ["watermelon", "mint", "lemon", "black salt", "sugar"], extraNeeded: ["ice"], instructions: ["Remove seeds from watermelon and cut into cubes.", "Add watermelon to a blender and blend until smooth.", "Strain through a fine sieve if you prefer a clear juice.", "Add lemon juice, black salt, sugar and mint leaves.", "Blend again briefly or stir well.", "Pour over crushed ice and serve immediately."] },
  { name: "Mango Panna", cuisine: "Juice", time: "15 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Raw mango cooler with roasted cumin and black salt.", ingredients: ["raw mango", "green mango", "cumin", "black salt", "sugar", "mint", "water"], extraNeeded: ["ice"], instructions: ["Boil or roast raw mango until the skin blisters. Cool and squeeze out the pulp.", "Dry roast cumin seeds until fragrant. Grind to a powder.", "Blend mango pulp with water, sugar, black salt and roasted cumin.", "Taste and adjust sweet-sour balance.", "Add fresh mint leaves and blend briefly.", "Strain, add ice and serve chilled."] },
  { name: "Carrot Ginger Juice", cuisine: "Juice", time: "10 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Fresh carrot and ginger blended with lemon.", ingredients: ["carrot", "ginger", "lemon", "apple", "honey"], extraNeeded: ["ice"], instructions: ["Wash and peel carrots. Peel apple and remove core.", "Cut into pieces suitable for your juicer or blender.", "Juice carrots, apple and ginger together.", "If using a blender, add a little water and strain through a sieve.", "Add lemon juice and honey. Stir well.", "Pour over ice and serve immediately for maximum nutrition."] },
  { name: "Pomegranate Juice", cuisine: "Juice", time: "10 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Freshly pressed pomegranate juice with lemon and mint.", ingredients: ["pomegranate", "lemon", "mint", "honey", "sugar"], extraNeeded: ["ice"], instructions: ["Cut pomegranate in half. Use a citrus juicer to press out juice from each half.", "Alternatively, remove seeds and blend with a little water, then strain.", "Add lemon juice, honey and a pinch of black salt.", "Stir well to combine.", "Add fresh mint leaves.", "Pour over ice and serve immediately."] },
  { name: "Pineapple Mint Cooler", cuisine: "Juice", time: "10 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Tangy pineapple juice with mint and ginger.", ingredients: ["pineapple", "mint", "ginger", "lemon", "honey", "sugar"], extraNeeded: ["ice"], instructions: ["Peel and core pineapple. Cut into chunks.", "Blend pineapple with ginger and a little water until smooth.", "Strain through a sieve to get a smooth juice.", "Add lemon juice, honey and sugar to taste.", "Muddle fresh mint leaves at the bottom of the glass.", "Pour juice over mint and ice. Stir and serve."] },
  { name: "Beetroot Apple Juice", cuisine: "Juice", time: "10 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Earthy beetroot and sweet apple blended with ginger.", ingredients: ["beetroot", "apple", "ginger", "lemon", "carrot"], extraNeeded: ["ice"], instructions: ["Peel and roughly chop beetroot, apple and carrot.", "Feed through a juicer with ginger, or blend with water and strain.", "Add freshly squeezed lemon juice.", "Stir and taste — adjust lemon for tartness.", "Pour over ice in a glass.", "Serve immediately while fresh and vibrant."] },
  // ── Milkshakes ──
  { name: "Mango Milkshake", cuisine: "Milkshake", time: "5 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Ripe Alphonso mangoes blended with chilled milk and sugar.", ingredients: ["mango", "milk", "sugar", "cardamom"], extraNeeded: ["ice cream"], instructions: ["Peel ripe mangoes and roughly chop the flesh.", "Add mango, chilled milk, sugar and a pinch of cardamom to a blender.", "Add a scoop of vanilla ice cream for extra richness.", "Blend until completely smooth and frothy.", "Taste and adjust sweetness.", "Pour into chilled glasses and serve immediately."] },
  { name: "Banana Milkshake", cuisine: "Milkshake", time: "5 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Ripe banana blended with cold milk, honey and cardamom.", ingredients: ["banana", "milk", "honey", "sugar", "cardamom"], extraNeeded: ["ice"], instructions: ["Peel ripe bananas and break into chunks.", "Add to a blender with chilled milk, honey and cardamom.", "Blend on high speed until smooth and thick.", "Add ice cubes and blend briefly.", "Taste and add more honey if needed.", "Pour into glasses and serve immediately."] },
  { name: "Strawberry Milkshake", cuisine: "Milkshake", time: "5 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Fresh strawberries blended with chilled milk and vanilla.", ingredients: ["strawberry", "milk", "sugar", "vanilla"], extraNeeded: ["ice cream"], instructions: ["Wash and hull strawberries. Slice a few for garnish.", "Add strawberries, chilled milk, sugar and vanilla extract to blender.", "Add a scoop of vanilla ice cream.", "Blend until smooth and creamy.", "Pour into a chilled glass.", "Garnish with a fresh strawberry on the rim and serve."] },
  { name: "Rose Milk", cuisine: "Milkshake", time: "5 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Chilled milk with rose syrup and basil seeds — South Indian street favourite.", ingredients: ["milk", "rose syrup", "sugar", "basil seeds", "sabja"], extraNeeded: ["ice"], instructions: ["Soak basil seeds (sabja) in water for 10 minutes until they swell into gel-coated seeds.", "Chill milk well.", "Add rose syrup to cold milk and stir. Adjust to taste.", "Add the soaked basil seeds.", "Pour over crushed ice in a tall glass.", "Stir once and serve immediately."] },
  { name: "Badam Milk", cuisine: "Milkshake", time: "15 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Almond milk infused with saffron, cardamom and pistachio.", ingredients: ["almond", "badam", "milk", "saffron", "cardamom", "sugar", "pistachio"], extraNeeded: [], instructions: ["Soak almonds overnight. Peel the skins off.", "Blanch peeled almonds and grind to a smooth paste with a little milk.", "Heat milk until warm. Add almond paste and stir well.", "Dissolve saffron in 2 tablespoons of warm milk, then add to the mixture.", "Add sugar, cardamom powder and simmer on low heat for 5 minutes.", "Serve warm or chilled, garnished with slivered pistachios."] },
  { name: "Lassi", cuisine: "Punjabi", time: "5 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Thick churned yogurt with sugar and cardamom.", ingredients: ["yogurt", "curd", "milk", "sugar", "cardamom"], extraNeeded: ["ice", "rose water"], instructions: ["Add thick yogurt, chilled milk, sugar and cardamom to a blender.", "Blend on high speed until very frothy.", "Add a few drops of rose water for fragrance.", "Pour into tall glasses over ice.", "Garnish with a thin layer of cream on top.", "Serve cold."] },
  { name: "Masala Buttermilk", cuisine: "South Indian", time: "5 min", difficulty: "Easy", diet: ["vegetarian", "gluten-free"], description: "Thin spiced yogurt drink with ginger, green chilli and curry leaves.", ingredients: ["yogurt", "curd", "water", "ginger", "green chilli", "curry leaves", "coriander", "cumin"], extraNeeded: ["asafoetida"], instructions: ["Whisk yogurt with water until smooth and thin.", "Add finely grated ginger, minced green chilli and salt.", "Add a pinch of roasted cumin powder and asafoetida.", "Heat a few drops of oil, splutter mustard seeds, add curry leaves and pour over buttermilk.", "Add chopped coriander and mix.", "Serve chilled — it is best as an afternoon cooler."] },
  // ── Fast Food ──
  { name: "Masala Dosa", cuisine: "Karnataka", time: "30 min", difficulty: "Medium", diet: ["vegetarian", "vegan", "gluten-free"], description: "Crispy fermented rice crepe stuffed with spiced potato filling — Karnataka's most iconic export.", ingredients: ["rice", "urad dal", "potato", "onion", "mustard seeds", "curry leaves", "turmeric", "green chilli", "ginger"], extraNeeded: ["oil"], instructions: ["Soak rice and urad dal separately for 6 hours. Grind to a smooth batter. Ferment overnight.", "Boil potatoes, peel and mash coarsely. Temper mustard seeds, curry leaves, onion, turmeric and mash into filling.", "Heat a dosa tawa, pour batter and spread into a thin circle with back of ladle.", "Drizzle oil on the edges. Cook until crispy golden on the bottom.", "Place potato filling in the centre and fold the dosa over.", "Serve immediately with coconut chutney and sambar."] },
  { name: "Vada Pav", cuisine: "Mumbai Street Food", time: "30 min", difficulty: "Easy", diet: ["vegetarian", "vegan"], description: "Deep-fried spiced potato fritter in a soft bun with chutneys.", ingredients: ["potato", "maida", "flour", "besan", "gram flour", "garlic", "green chilli", "mustard seeds", "turmeric"], extraNeeded: ["pav buns", "green chutney"], instructions: ["Boil and mash potatoes. Temper mustard seeds, garlic and green chilli in oil. Mix into mashed potato.", "Shape into round balls (vada).", "Make a thick besan batter with turmeric, chilli and salt.", "Dip each vada in batter and deep fry until golden.", "Slit a pav bun, apply dry garlic chutney and green chutney on inside.", "Place the hot vada inside and serve immediately."] },
  { name: "Bread Pakora", cuisine: "Fast Food", time: "20 min", difficulty: "Easy", diet: ["vegetarian", "vegan"], description: "Bread stuffed with spiced potato, dipped in besan batter and deep fried.", ingredients: ["bread", "potato", "besan", "gram flour", "onion", "green chilli", "ginger", "coriander", "turmeric"], extraNeeded: ["oil", "chutney"], instructions: ["Boil and mash potatoes. Mix with onion, green chilli, ginger, coriander and salt.", "Make a smooth thick batter with besan, turmeric, chilli and water.", "Spread potato filling on a bread slice and top with another slice.", "Dip the sandwich in besan batter, coating all sides.", "Deep fry in hot oil until golden and crispy on all sides.", "Cut diagonally and serve hot with green chutney."] },
  { name: "Gobi 65", cuisine: "Fast Food", time: "25 min", difficulty: "Easy", diet: ["vegetarian", "vegan"], description: "Crispy fried cauliflower in a spicy tangy coating.", ingredients: ["cauliflower", "besan", "gram flour", "maida", "flour", "garlic", "ginger", "red chilli", "turmeric", "curd", "yogurt"], extraNeeded: ["oil", "curry leaves"], instructions: ["Cut cauliflower into florets. Blanch briefly in salted hot water for 3 minutes. Drain and dry.", "Mix besan, maida, yogurt, garlic paste, ginger paste, red chilli, turmeric and salt into a thick batter.", "Coat cauliflower florets in the batter.", "Deep fry in hot oil until golden and crispy. Drain.", "Heat a little oil, fry curry leaves and toss with the fried cauliflower.", "Squeeze lemon, garnish with coriander and serve hot."] },
  { name: "Chicken 65", cuisine: "Fast Food", time: "25 min", difficulty: "Easy", diet: ["non-veg", "gluten-free"], description: "Spicy deep-fried chicken bites — a South Indian bar snack legend.", ingredients: ["chicken", "yogurt", "curd", "red chilli", "garlic", "ginger", "turmeric", "lemon", "curry leaves"], extraNeeded: ["oil", "corn starch"], instructions: ["Cut chicken into bite-sized pieces.", "Marinate in yogurt, garlic paste, ginger paste, red chilli, turmeric, lemon juice and salt for 1 hour.", "Add corn starch to the marinade and mix well.", "Deep fry in hot oil until golden and crispy, about 6-8 minutes.", "In a separate pan, heat oil and fry curry leaves and dry red chilli.", "Toss fried chicken with the curry leaves tempering. Serve with onion rings and lemon."] },
  { name: "Pani Puri", cuisine: "Street Food", time: "30 min", difficulty: "Medium", diet: ["vegetarian", "vegan", "gluten-free"], description: "Crispy hollow puris filled with spiced potato-chickpea mix and tangy pani.", ingredients: ["potato", "chickpeas", "chana", "tamarind", "mint", "coriander", "cumin", "black salt", "green chilli", "lemon"], extraNeeded: ["puri shells"], instructions: ["For filling: boil chickpeas and mash roughly with potato, salt and spices.", "For pani: blend mint, coriander, green chilli, lemon, black salt, cumin with ice cold water until smooth.", "Strain pani through a fine sieve. Adjust sourness and salt.", "Make a small hole in the top of each puri shell.", "Fill with potato-chickpea mixture.", "Dip filled puri fully into the pani and eat in one bite immediately."] },
  { name: "Aloo Tikki", cuisine: "Street Food", time: "25 min", difficulty: "Easy", diet: ["vegetarian", "vegan", "gluten-free"], description: "Crispy shallow-fried potato patties spiced with cumin and coriander.", ingredients: ["potato", "onion", "green chilli", "ginger", "coriander", "cumin", "breadcrumbs", "bread"], extraNeeded: ["oil", "chutney"], instructions: ["Boil and mash potatoes until smooth. Cool completely.", "Mix with onion, green chilli, ginger, coriander, cumin, salt and breadcrumbs.", "Divide into equal portions and shape into flat round patties.", "Refrigerate for 15 minutes so they firm up and hold shape.", "Shallow fry in oil on medium heat until golden and crispy on both sides.", "Serve hot with tamarind chutney and green chutney."] },
  { name: "Spring Rolls", cuisine: "Fast Food", time: "30 min", difficulty: "Medium", diet: ["vegetarian", "vegan"], description: "Crispy rolls stuffed with stir-fried vegetables and glass noodles.", ingredients: ["cabbage", "carrot", "onion", "capsicum", "bell pepper", "garlic", "ginger", "soy sauce", "noodles"], extraNeeded: ["spring roll sheets", "oil"], instructions: ["Soak glass noodles until soft. Chop into short lengths.", "Stir fry all vegetables with garlic, ginger and soy sauce on high heat until cooked but crunchy.", "Mix in noodles and season. Cool the filling completely.", "Place a spring roll sheet at a diagonal. Add filling in the lower third.", "Fold the bottom corner up, then fold sides in and roll tightly. Seal with a flour-water paste.", "Deep fry until golden and crispy. Serve with sweet chilli sauce."] },
  { name: "Cheese Toast", cuisine: "Fast Food", time: "10 min", difficulty: "Easy", diet: ["vegetarian"], description: "Toasted bread topped with cheese, onion, capsicum and chilli flakes.", ingredients: ["bread", "cheese", "onion", "capsicum", "bell pepper", "butter", "garlic", "green chilli"], extraNeeded: ["chilli flakes"], instructions: ["Apply butter mixed with garlic paste on each bread slice.", "Layer with finely chopped onion, capsicum and green chilli.", "Generously grate or place cheese slices on top.", "Toast in a preheated oven or grill at 180°C until cheese melts and bubbles.", "Sprinkle chilli flakes on top.", "Cut diagonally and serve hot immediately."] },
];

